(777,823,$mw$6D8279E00D36DE25A301097D034F2A53F32A801464FCE605910687E6DA00E681$mw$,$mw$15b8a1fa653c14f6dccd689206c5d615$mw$,$mw$$mw$,$mw${"Id":823,"StageId":2,"CategoryId":22,"Points":10,"TitleAr":"قراءة مفتاح المخطط التصويري والمقارنة","TitleEn":"Interpret a pictograph key and compare quantities","QuestionTextAr":"في مخطط تصويري للكتب، كل رمز ★ يمثّل 4 كتب. يظهر لدى المجموعة أ ستة رموز ولدى المجموعة ب ثلاثة رموز. كم كتاباً تزيد المجموعة أ عن ب؟","QuestionTextEn":"In a book pictograph, each star represents 4 books. Group A has six stars and group B has three stars. How many more books does group A have?","DetailedSolutionAr":"المبدأ المستخدم: قيمة الرمز الواحد في المخطط المصور = 4 كتب. لدى المجموعة أ ست نجوم فتُمثّل 6 × 4 = 24 كتاباً، ولدى ب ثلاث نجوم فتُمثّل 3 × 4 = 12 كتاباً. الفرق = 24 − 12 = 12 كتاباً، وليس ثلاث نجوم فقط.","DetailedSolutionEn":"Rule used: In a pictograph, each star stands for 4 books. Group A's six stars represent 6 × 4 = 24 books; B's three stars represent 3 × 4 = 12 books. Difference = 24 − 12 = 12 books, not merely three symbols.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":3281,"Order":1,"LatexCode":"3","IsCorrect":false},{"Id":3282,"Order":2,"LatexCode":"9","IsCorrect":false},{"Id":3283,"Order":3,"LatexCode":"12","IsCorrect":true},{"Id":3284,"Order":4,"LatexCode":"36","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"انتبه إلى مفتاح المخطط.","En":"Check the pictograph key."},{"Ar":"اطرح عدد النجوم ثم اضرب الفرق بقيمة النجمة.","En":"Subtract the star counts, then multiply by the value per star."}],"Title":{"Ar":"قراءة مفتاح المخطط التصويري والمقارنة","En":"Interpret a pictograph key and compare quantities"},"Points":10,"Options":[{"LatexCode":"3","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"3 فرق الرموز فقط، وكل رمز أربعة كتب.","En":"Three is the symbol difference only; each symbol is four books."}},{"LatexCode":"9","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"9 مجموع الرموز وليس فرق الكتب.","En":"Nine counts all symbols rather than the difference in books."}},{"LatexCode":"12","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"36","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"36 مجموع كتب المجموعتين.","En":"Thirty-six is the combined book count."}}],"StageId":2,"Question":{"Ar":"في مخطط تصويري للكتب، كل رمز ★ يمثّل 4 كتب. يظهر لدى المجموعة أ ستة رموز ولدى المجموعة ب ثلاثة رموز. كم كتاباً تزيد المجموعة أ عن ب؟","En":"In a book pictograph, each star represents 4 books. Group A has six stars and group B has three stars. How many more books does group A have?"},"Solution":{"Idea":{"Ar":"كل رمز في المخطط يمثل عدداً ثابتاً من الكتب.","En":"Each pictograph symbol represents a fixed number of books."},"Unit":{"Ar":"عدد","En":"Count"},"Steps":[{"Ar":"مفتاح المخطط يحدد أربعة كتب لكل نجمة.","En":"The key specifies four books per star."},{"Ar":"المجموعة A فيها 6×4=24 كتاباً، وB فيها 3×4=12 كتاباً.","En":"Group A has 6×4=24 books, and B has 3×4=12 books."},{"Ar":"نطرح العدد الأصغر من الأكبر فنحصل على 12 كتاباً.","En":"Subtract the smaller count from the larger to get twelve books."}],"Result":{"Ar":"$12$","En":"$12$"},"CommonError":{"Ar":"لا تعتبر الرمز كتاباً واحداً إذا كان المفتاح يحدد أربعة.","En":"Do not treat a symbol as one book when the key specifies four."},"FormulaLatex":"D=(6-3)\\cdot4","Substitution":{"Ar":"$24-12=12$","En":"$24-12=12$"},"Verification":{"Ar":"$(6-3)\\cdot4=12$","En":"$(6-3)\\cdot4=12$"}},"TrackIds":[7],"CategoryId":22,"PrimarySkillId":100,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"انتبه إلى مفتاح المخطط.","En":"Check the pictograph key."},{"Ar":"اطرح عدد النجوم ثم اضرب الفرق بقيمة النجمة.","En":"Subtract the star counts, then multiply by the value per star."}],"Solution":{"Idea":{"Ar":"كل رمز في المخطط يمثل عدداً ثابتاً من الكتب.","En":"Each pictograph symbol represents a fixed number of books."},"Unit":{"Ar":"عدد","En":"Count"},"Steps":[{"Ar":"مفتاح المخطط يحدد أربعة كتب لكل نجمة.","En":"The key specifies four books per star."},{"Ar":"المجموعة A فيها 6×4=24 كتاباً، وB فيها 3×4=12 كتاباً.","En":"Group A has 6×4=24 books, and B has 3×4=12 books."},{"Ar":"نطرح العدد الأصغر من الأكبر فنحصل على 12 كتاباً.","En":"Subtract the smaller count from the larger to get twelve books."}],"Result":{"Ar":"$12$","En":"$12$"},"CommonError":{"Ar":"لا تعتبر الرمز كتاباً واحداً إذا كان المفتاح يحدد أربعة.","En":"Do not treat a symbol as one book when the key specifies four."},"FormulaLatex":"D=(6-3)\\cdot4","Substitution":{"Ar":"$24-12=12$","En":"$24-12=12$"},"Verification":{"Ar":"$(6-3)\\cdot4=12$","En":"$(6-3)\\cdot4=12$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"3 فرق الرموز فقط، وكل رمز أربعة كتب.","En":"Three is the symbol difference only; each symbol is four books."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"9 مجموع الرموز وليس فرق الكتب.","En":"Nine counts all symbols rather than the difference in books."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"36 مجموع كتب المجموعتين.","En":"Thirty-six is the combined book count."},"Order":4}]}$mw$,$mw$كل رمز في المخطط يمثل عدداً ثابتاً من الكتب.

$D=(6-3)\cdot4$

1. مفتاح المخطط يحدد أربعة كتب لكل نجمة.

2. المجموعة A فيها 6×4=24 كتاباً، وB فيها 3×4=12 كتاباً.

3. نطرح العدد الأصغر من الأكبر فنحصل على 12 كتاباً.

$24-12=12$

$12$ عدد

$(6-3)\cdot4=12$

لا تعتبر الرمز كتاباً واحداً إذا كان المفتاح يحدد أربعة.$mw$,$mw$Each pictograph symbol represents a fixed number of books.

$D=(6-3)\cdot4$

1. The key specifies four books per star.

2. Group A has 6×4=24 books, and B has 3×4=12 books.

3. Subtract the smaller count from the larger to get twelve books.

$24-12=12$

$12$ Count

$(6-3)\cdot4=12$

Do not treat a symbol as one book when the key specifies four.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
